package com.aistock.market.adminquery;

import com.aistock.common.*;import com.aistock.market.security.SessionIdentityClient;import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminMarketReadHttpTest {
 SessionIdentityClient identity;AdminMarketReadRepository repo;MockMvc mvc;ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();String base="/api/v1/admin/market-data";Cookie cookie=new Cookie("AISTOCK_SESSION","admin");
 @BeforeEach void init(){identity=mock(SessionIdentityClient.class);repo=mock(AdminMarketReadRepository.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("00000000-0000-0000-0000-000000000001","ADMIN",false,0),"test"));when(repo.heads(any(),any())).thenAnswer(x->new AdminMarketRecords.HeadPage(AdminMarketReadMysqlTest.NOW,AdminMarketRecords.DEFINITION,x.getArgument(0),List.of(),false));mvc=MockMvcBuilders.standaloneSetup(new AdminMarketReadController(repo,Clock.fixed(AdminMarketReadMysqlTest.NOW,ZoneOffset.UTC))).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminMarketDataAccessFilter(identity,"server-test",mapper)).build();}
 @Test void roleGuardExactGetAndSingletonParameters()throws Exception{mvc.perform(get(base)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get(base).cookie(cookie)).andExpect(status().isOk()).andExpect(jsonPath("$.data.definitionVersion").value(AdminMarketRecords.DEFINITION));mvc.perform(get(base).cookie(cookie,cookie)).andExpect(status().isUnauthorized());mvc.perform(get(base).cookie(cookie).param("page","1","2")).andExpect(status().isBadRequest());mvc.perform(post(base).cookie(cookie)).andExpect(status().isNotFound());mvc.perform(get(base+"/unknown").cookie(cookie)).andExpect(status().isNotFound());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("00000000-0000-0000-0000-000000000001","USER",false,0),"test"));mvc.perform(get(base).cookie(cookie).header("X-Role","ADMIN")).andExpect(status().isForbidden());verify(repo,times(1)).heads(any(),any());}
 @Test void actualJsonIdentityRejectsCoercionAndSafeDependencyFailures()throws Exception{for(var field:List.of("",",\"credentialVersion\":null",",\"credentialVersion\":1.5",",\"credentialVersion\":\"2\"")){var json="{\"userId\":\"00000000-0000-0000-0000-000000000001\",\"role\":\"ADMIN\",\"experimentAllowed\":false"+field+"}";doAnswer(x->ApiResponse.success(mapper.convertValue(mapper.readTree(json),SessionIdentityClient.Identity.class),"test")).when(identity).resolve(any(),anyString());mvc.perform(get(base).cookie(cookie)).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("USER_SERVICE_UNAVAILABLE"));}verifyNoInteractions(repo);}
}
